from datetime import datetime, timezone

RETRYABLE_STATUSES = {429, 502, 503, 504}
IDEMPOTENT_METHODS = {"GET", "HEAD", "OPTIONS", "PUT", "DELETE"}
DEFAULT_PROFILE = (5, 8.0, 120)
PROFILES = {
    "shipping": (8, 3.0, 40),
    "catalog": (6, 8.0, 30),
    "ledger": (8, 3.0, 60),
    "auth": (6, 6.0, 20),
    "payments": (3, 1.0, 30),
    "reports": (9, 5.0, 120),
    "inventory": (7, 4.0, 90),
    "media": (5, 8.0, 15),
    "ledger-export": (4, 8.0, 10),
    "search": (10, 12.0, 45),
}
MONTHS = {
    name: index
    for index, name in enumerate(
        ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"], 1
    )
}
DAYS = ("Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun")
HTTP_DATE = re.compile(
    r"([A-Z][a-z]{2}), (\\d{2}) ([A-Z][a-z]{2}) (\\d{4}) (\\d{2}):(\\d{2}):(\\d{2}) GMT"
)


def _header(headers, name):
    for key, value in (headers or {}).items():
        if key.lower() == name:
            return value
    return None


def _parse_retry_after(value, now):
    if value is None:
        return None
    value = value.strip()
    if re.fullmatch(r"[0-9]+", value):
        return float(int(value))
    match = HTTP_DATE.fullmatch(value)
    if not match:
        return None
    day_name, day, month, year, hour, minute, second = match.groups()
    if month not in MONTHS or day_name not in DAYS:
        return None
    try:
        when = datetime(
            int(year), MONTHS[month], int(day), int(hour), int(minute), int(second),
            tzinfo=timezone.utc,
        )
    except ValueError:
        return None
    if DAYS[when.weekday()] != day_name:
        return None
    return max(0.0, (when - now).total_seconds())
''',1)
s=s.replace("    raise NotImplementedError\n",'''    if status is not None and status not in RETRYABLE_STATUSES:
        return None
    if method.upper() not in IDEMPOTENT_METHODS:
        key = _header(request_headers, "idempotency-key")
        if method.upper() not in ("POST", "PATCH") or not key or not key.strip():
            return None
    service = (_header(request_headers, "x-service") or "").strip().lower()
    max_attempts, cap, max_wait = PROFILES.get(service, DEFAULT_PROFILE)
    if attempt >= max_attempts:
        return None
    delay = min(0.25 * 2 ** (attempt - 1), cap)
    if status in (429, 503):
        wait = _parse_retry_after(_header(response_headers, "retry-after"), now)
        if wait is not None:
            if wait > max_wait:
                return None
            delay = max(delay, wait)
    return delay
''')
open(p,'w').write(s)
